import React from "react";
import Myinfo from "./myInfoProfileComponent";

class Profile extends React.Component {
    render() {
        return (
            <>
                <main className="container mt-4 pt-5">
                    <div className="container-fluid mt-5">
                        <Myinfo/>
                        
                    </div>
                </main>
            </>
        );
    }
}
export default Profile;
